const MAX_RETRIES: u32 = 3;

fn main() {
    let attempts = 0;
    // attempts += 1;          // error: cannot assign twice to immutable variable
    let mut tries = attempts;
    tries += 1;

    let input = "  42  ";
    let input = input.trim();              // shadow: still &str
    let input: i32 = input.parse().unwrap(); // shadow: now i32

    println!("{tries}/{MAX_RETRIES}, value = {input}"); // 1/3, value = 42
}

fn main() {
    let big: u64 = 10_000_000_000;
    let small: i32 = -7;
    // let sum = big + small;            // error: mismatched types
    let sum = big as i64 + small as i64; // explicit conversion
    let byte = u8::try_from(300).ok();   // None: does not fit
    let capped = 250u8.saturating_add(10); // 255

    let c = 'é';                         // a char is a Unicode scalar value
    let point: (f64, f64) = (1.5, -2.0);
    let (x, y) = point;                  // destructure a tuple
    let grid = [0u8; 4];                 // [0, 0, 0, 0]

