}

fn classify(n: i32) -> &'static str {
    if n < 0 {
        return "negative"; // early return
    }
    let kind = if n % 2 == 0 { "even" } else { "odd" };
    kind
}

fn main() {
    let total = {
        let a = area(2.0, 3.5);
        a + 1.0 // block evaluates to 8.0
    };
    println!("{total} {} {}", classify(-3), classify(4)); // 8 negative even
}

fn main() {
    let items = ["ant", "bee", "cat"];
    for (i, name) in items.iter().enumerate() {
        println!("{i}: {name}");
    }

    let mut n = 27u64;
    let steps = loop {
        // loop is an expression; break returns a value
        if n == 1 { break 0; }
        let mut count = 0;
        while n != 1 {
            n = if n % 2 == 0 { n / 2 } else { 3 * n + 1 };
            count += 1;
        }
        break count;
    };
    println!("steps = {steps}"); // steps = 111

    'outer: for x in 1..=3 {
        for y in 1..=3 {
            if x * y == 4 { println!("found {x}*{y}"); break 'outer; }
        }
    }
}

fn take(s: String) -> usize {
    s.len() // s is dropped here; its heap buffer is freed
}

fn main() {
    let a = String::from("hello");
    let b = a;                 // move: a is no longer valid
    // println!("{a}");        // error[E0382]: borrow of moved value: `a`

    let c = b.clone();         // explicit deep copy
    let n = take(b);           // b moved into the function
    println!("{c} {n}");       // hello 5

    let x = 5;
    let y = x;                 // i32 is Copy: x is still usable
    println!("{x} {y}");
}

fn total_len(words: &[String]) -> usize {
    words.iter().map(|w| w.len()).sum()
}

fn shout(s: &mut String) {
    s.push('!');
}

fn main() {
    let mut words = vec![String::from("hi"), String::from("there")];
    let first = &words[0];          // shared borrow
    println!("first = {first}");    // last use of `first`
    words.push(String::from("again")); // OK: shared borrow has ended

    shout(&mut words[1]);
    println!("{:?} {}", words, total_len(&words)); // ["hi", "there!", "again"] 13

    let mut n = 1;
    let r = &mut n;
    *r += 1;                        // explicit dereference
    println!("{n}");                // 2
}

fn first_word(s: &str) -> &str {
    match s.find(' ') {
        Some(i) => &s[..i],
        None => s,
    }
}

fn sum(xs: &[i32]) -> i32 {
    xs.iter().sum()
}

fn main() {
    let owned = String::from("hello world");
    println!("{}", first_word(&owned));       // hello  (&String -> &str)
    println!("{}", first_word("one-word"));   // one-word (literal is &str)

    let v = vec![1, 2, 3, 4];
    let arr = [10, 20];
    println!("{} {}", sum(&v[1..3]), sum(&arr)); // 5 30

    let mut nums = [3, 1, 2];
