    println!("{nums:?}");                        // [1, 2, 3]
}

#[derive(Debug)]
struct Rectangle {
    width: u32,
    height: u32,
}

impl Rectangle {
    fn new(width: u32, height: u32) -> Self {   // associated function
        Self { width, height }                   // field init shorthand
    }
    fn square(size: u32) -> Self {
        Self::new(size, size)
    }
    fn area(&self) -> u32 { self.width * self.height }
    fn scale(&mut self, k: u32) { self.width *= k; self.height *= k; }
    fn into_tuple(self) -> (u32, u32) { (self.width, self.height) }
}

fn main() {
    let mut r = Rectangle::new(3, 4);
    r.scale(2);
    println!("{} {:?}", r.area(), Rectangle::square(2)); // 48 Rectangle { width: 2, height: 2 }
    let (w, h) = r.into_tuple();                         // r is consumed
    println!("{w}x{h}");                                 // 6x8
}

enum Shape {
    Circle { radius: f64 },
    Rect(f64, f64),
    Empty,
}
impl Shape {
    fn area(&self) -> f64 {
        match self {
            Shape::Circle { radius } => std::f64::consts::PI * radius * radius,
            Shape::Rect(w, h) => w * h,
            Shape::Empty => 0.0,
        }
    }
}

fn main() {
    let shapes = [Shape::Rect(2.0, 3.0), Shape::Circle { radius: 1.0 }, Shape::Empty];
    for s in &shapes {
        let label = match s {
            Shape::Empty => "nothing",
            _ => "something",
        };
        println!("{label}: {:.2}", s.area()); // something: 6.00 / 3.14 / nothing: 0.00
    }
}

fn parse_port(s: &str) -> Option<u16> {
    s.strip_prefix("port=")?.parse().ok() // ? on Option returns None early
}

fn describe(config: &[&str]) -> String {
    let Some(first) = config.first() else {
        return "empty".to_string(); // else block must diverge
    };
    if let Some(port) = parse_port(first) && port >= 1024 {
        format!("user port {port}")
    } else {
        String::from("no user port")
    }
}

fn main() {
    println!("{}", describe(&["port=8080"])); // user port 8080
    println!("{}", describe(&["port=80"]));   // no user port
    println!("{}", describe(&[]));            // empty

    let name: Option<&str> = None;
    println!("{}", name.map(|n| n.len()).unwrap_or(0)); // 0
}

struct Point { x: i32, y: i32 }

fn classify(p: &Point) -> String {
    match p {
        Point { x: 0, y: 0 } => "origin".into(),
        Point { x, y: 0 } | Point { x: 0, y: x } => format!("on an axis at {x}"),
        Point { x, y } if x == y => "on the diagonal".into(),
        Point { x: px @ 1..=9, .. } => format!("small positive x = {px}"),
        _ => "elsewhere".into(),
    }
}

fn main() {
    for p in [Point { x: 0, y: 0 }, Point { x: 0, y: 5 }, Point { x: 3, y: 3 }, Point { x: 4, y: 7 }] {
        println!("{}", classify(&p)); // origin / on an axis at 5 / on the diagonal / small positive x = 4
    }
    let scores = vec![90, 72, 85];
    if let [first, .., last] = scores.as_slice() {
        println!("{first}..{last}"); // 90..85
    }
    let mut stack = vec![1, 2, 3];
    while let Some(top) = stack.pop() { print!("{top} "); } // 3 2 1
}

use std::num::ParseIntError;

fn parse_pair(s: &str) -> Result<(i32, i32), String> {
    let (a, b) = s.split_once(',').ok_or("missing comma")?;
    let a: i32 = a.trim().parse().map_err(|e: ParseIntError| e.to_string())?;
    let b: i32 = b.trim().parse().map_err(|e: ParseIntError| e.to_string())?;
    Ok((a, b))
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("{:?}", parse_pair("3, 4"));  // Ok((3, 4))
    println!("{:?}", parse_pair("3 4"));   // Err("missing comma")
    println!("{:?}", parse_pair("3, x"));  // Err("invalid digit found in string")

    let n: u8 = "200".parse()?;            // ParseIntError converts into Box<dyn Error>
    println!("n = {n}");
    Ok(())
}

fn main() {
    let mut scores: Vec<u32> = Vec::with_capacity(4);
    scores.extend([70, 95, 82]);
    scores.push(95);

    println!("{:?} {:?}", scores.get(10), scores.first()); // None Some(70)

    for s in &mut scores {
        *s += 5; // in-place edit through &mut
    }
    scores.sort_unstable();
    scores.dedup();
    scores.retain(|&s| s >= 80);
    println!("{scores:?} len={} cap>={}", scores.len(), scores.capacity()); // [87, 100] len=2 cap>=4

    let pairs: Vec<&[u32]> = [1, 2, 3, 4].windows(2).collect::<Vec<_>>();
    println!("{pairs:?}"); // [[1, 2], [2, 3], [3, 4]]

    let total: u32 = scores.into_iter().sum(); // consumes the vector
    println!("{total}"); // 187
}

