use std::collections::{BTreeMap, HashMap, HashSet};

fn main() {
    let text = "the quick cat and the lazy dog and the cat";

    let mut counts: HashMap<&str, usize> = HashMap::new();
    for word in text.split_whitespace() {
        *counts.entry(word).or_insert(0) += 1;
    }
    println!("the = {:?}, cow = {:?}", counts.get("the"), counts.get("cow")); // Some(3), None

    let mut by_len: BTreeMap<usize, Vec<&str>> = BTreeMap::new();
    for word in text.split_whitespace() {
        by_len.entry(word.len()).or_default().push(word);
    }
    println!("{:?}", by_len.keys().collect::<Vec<_>>()); // [3, 4, 5]: sorted keys
    println!("{:?}", by_len[&5]);                          // ["quick"]

    let unique: HashSet<&str> = text.split_whitespace().collect();
    println!("{} unique words", unique.len()); // 6 unique words
}

