use std::fmt::Display;

trait Summary {
    fn author(&self) -> String;
    fn summarize(&self) -> String { format!("(Read more from {}...)", self.author()) } // default
}

struct Tweet { user: String, text: String }
struct Article { by: String }
impl Summary for Tweet {
    fn author(&self) -> String { format!("@{}", self.user) }
    fn summarize(&self) -> String { format!("{}: {}", self.author(), self.text) } // override
}
impl Summary for Article {
    fn author(&self) -> String { self.by.clone() }
}

fn notify(item: &impl Summary) { println!("Breaking! {}", item.summarize()); }
fn loud<T: Display>(x: T) -> impl Display { format!("{x}!") }

fn main() {
    notify(&Tweet { user: "rustlang".into(), text: "1.88 is out".into() }); // Breaking! @rustlang: 1.88 is out
    notify(&Article { by: "Ferris".into() }); // Breaking! (Read more from Ferris...)
    println!("{}", loud(42));                 // 42!
}

use std::fmt::Display;

fn largest<T: PartialOrd>(items: &[T]) -> &T {
    let mut best = &items[0];
    for item in items {
        if item > best { best = item; }
    }
    best
}

struct Pair<T> { a: T, b: T }
impl<T> Pair<T> where T: Display + PartialOrd { // methods only for comparable, printable T
    fn show_max(&self) {
        let m = if self.a > self.b { &self.a } else { &self.b };
        println!("max = {m}");
    }
}
fn sum_all<const N: usize>(xs: [i32; N]) -> i32 { xs.iter().sum() }

fn main() {
    println!("{} {}", largest(&[3, 9, 2]), largest(&["kiwi", "apple"])); // 9 kiwi
    Pair { a: 1.5, b: 0.5 }.show_max();                                 // max = 1.5
    let v = "1 2 3".split(' ').map(|s| s.parse::<i32>().unwrap()).collect::<Vec<_>>();
    println!("{v:?} {}", sum_all([1, 2, 3, 4]));                        // [1, 2, 3] 10
}

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Default)]
enum Level { #[default] Low, Mid, High }

#[derive(Debug, Clone, PartialEq, Default)]
struct Reading { celsius: f64, level: Level }

impl fmt::Display for Reading {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:.1}°C ({:?})", self.celsius, self.level)
    }
}
impl From<f64> for Reading {
    fn from(celsius: f64) -> Self {
        Reading { celsius, level: if celsius > 30.0 { Level::High } else { Level::Mid } }
    }
