fn main() {
    let r: Reading = 31.5.into();             // Into comes free with From<f64>
    println!("{r} / {r:?}");                  // 31.5°C (High) / Reading { celsius: 31.5, level: High }
    println!("{}", Level::Low < Level::High); // true: variant order
    println!("{}", Reading::default());       // 0.0°C (Low)
}

fn apply_twice<F: FnMut()>(mut f: F) { f(); f(); }

fn make_multiplier(k: i32) -> impl Fn(i32) -> i32 {
    move |x| x * k // `move`: the closure owns its copy of k
}

fn main() {
    let mut count = 0;
    apply_twice(|| count += 1);        // captures &mut count -> FnMut
    println!("count = {count}");       // count = 2

    let triple = make_multiplier(3);
    println!("{}", triple(7));         // 21

    let name = String::from("ferris");
    let consume = move || name;        // moves name out when called -> FnOnce only
    let back = consume();
    // consume();                      // error: closure cannot be called twice
    println!("{back}");

    let ops: Vec<Box<dyn Fn(i32) -> i32>> = vec![Box::new(|x| x + 1), Box::new(triple)];
    println!("{:?}", ops.iter().map(|f| f(10)).collect::<Vec<_>>()); // [11, 30]
}

struct Countdown(u32);

impl Iterator for Countdown {
    type Item = u32;
    fn next(&mut self) -> Option<u32> {
        if self.0 == 0 { return None; }
        self.0 -= 1;
        Some(self.0 + 1)
    }
}
fn main() {
    let words = ["apple", "bob", "kayak", "rust"];
    let palindromes: Vec<String> = words.iter()
        .filter(|w| w.chars().eq(w.chars().rev()))
        .map(|w| w.to_uppercase())
        .collect();
    println!("{palindromes:?}"); // ["BOB", "KAYAK"]

    let nums: Result<Vec<i32>, _> = "1,2,x".split(',').map(str::parse::<i32>).collect();
    println!("{}", nums.is_err()); // true: stops at the first error

    let total: u32 = Countdown(4).zip(1..).map(|(a, b)| a * b).sum();
    println!("{total}"); // 4*1 + 3*2 + 2*3 + 1*4 = 20
    println!("{:?}", words.iter().max_by_key(|w| w.len())); // Some("kayak"): last maximum wins
}

fn longer<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() >= y.len() { x } else { y }
}

struct Parser<'a> { input: &'a str, pos: usize }

impl<'a> Parser<'a> {
    // returns a slice of the input, valid for 'a, not tied to the &mut self borrow
    fn next_word(&mut self) -> Option<&'a str> {
        let rest = self.input[self.pos..].trim_start();
        if rest.is_empty() { return None; }
        let start = self.input.len() - rest.len();
        let end = rest.find(' ').map_or(self.input.len(), |i| start + i);
        self.pos = end;
        Some(&self.input[start..end])
    }
}

fn main() {
    let text = String::from("borrow checker rules");
    let mut p = Parser { input: &text, pos: 0 };
    let a = p.next_word().unwrap();
    let b = p.next_word().unwrap(); // `a` stays valid: it borrows text, not p
    println!("{}", longer(a, b));   // checker
}

