use std::cell::RefCell;
use std::rc::{Rc, Weak};

enum List { Cons(i32, Box<List>), Nil } // Box gives the recursive type a known size
fn sum(list: &List) -> i32 {
    match list { List::Cons(v, rest) => v + sum(rest), List::Nil => 0 }
}

#[derive(Default)]
struct Node {
    name: String,
    parent: RefCell<Weak<Node>>,      // non-owning back link
    children: RefCell<Vec<Rc<Node>>>, // owning links
}

fn main() {
    let list = List::Cons(1, Box::new(List::Cons(2, Box::new(List::Nil))));
    println!("sum = {}", sum(&list)); // sum = 3
    let root = Rc::new(Node { name: "root".into(), ..Default::default() });
    let leaf = Rc::new(Node { name: "leaf".into(), ..Default::default() });
    root.children.borrow_mut().push(Rc::clone(&leaf));
    *leaf.parent.borrow_mut() = Rc::downgrade(&root);
    let parent = leaf.parent.borrow().upgrade().map(|p| p.name.clone());
    println!("{parent:?}, leaf strong = {}", Rc::strong_count(&leaf)); // Some("root"), leaf strong = 2
}

use std::fmt::Debug;

// T: 'static means T owns its data (no short borrows), so it may move to another thread
fn spawn_print<T: Debug + Send + 'static>(value: T) -> std::thread::JoinHandle<()> {
    std::thread::spawn(move || println!("{value:?}"))
}

// higher-ranked: f must work for whatever lifetime each call gets
fn apply_all<F>(items: &[String], f: F) -> Vec<&str>
where
    F: for<'x> Fn(&'x str) -> &'x str,
{
    items.iter().map(|s| f(s)).collect()
}
// 2024 edition: the hidden type would capture the borrow of `v`; use<> says it borrows nothing
fn snapshot(v: &[u32]) -> impl Iterator<Item = u32> + use<> { v.to_vec().into_iter() }

fn main() {
    spawn_print(String::from("owned is 'static")).join().unwrap();
    println!("{:?}", apply_all(&["  a ".into(), " b".into()], str::trim)); // ["a", "b"]
    let mut ids = vec![1, 2];
    let snap = snapshot(&ids);
    ids.push(3);                                 // allowed: snap does not borrow ids
    println!("{:?}", snap.collect::<Vec<_>>());  // [1, 2]
}

use std::fmt::Debug;

trait Shape: Debug {
    fn area(&self) -> f64;
    fn name(&self) -> String { "shape".into() }
    fn scaled(&self, k: f64) -> Self where Self: Sized; // excluded from the vtable
}
#[derive(Debug)] struct Circle(f64);
#[derive(Debug)] struct Square(f64);
impl Shape for Circle {
    fn area(&self) -> f64 { 3.14159 * self.0 * self.0 }
    fn scaled(&self, k: f64) -> Self { Circle(self.0 * k) }
}
impl Shape for Square {
    fn area(&self) -> f64 { self.0 * self.0 }
    fn scaled(&self, k: f64) -> Self { Square(self.0 * k) }
}

fn main() {
    let shapes: Vec<Box<dyn Shape>> = vec![Box::new(Circle(1.0)), Box::new(Square(2.0).scaled(2.0))];
    println!("{:.2}", shapes.iter().map(|s| s.area()).sum::<f64>()); // 19.14
    let as_debug: &dyn Debug = shapes[1].as_ref();                   // trait upcasting (1.86+)
    println!("{as_debug:?} {}", shapes[0].name());                   // Square(4.0) shape
    println!("{}", size_of::<&dyn Shape>() == 2 * size_of::<usize>()); // true: fat pointer
}

use std::{error::Error, fmt, num::ParseIntError};
#[derive(Debug)] enum ConfigError { MissingKey(&'static str), BadPort(ParseIntError) }
impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Self::MissingKey(k) => write!(f, "missing key `{k}`"),
            Self::BadPort(_) => write!(f, "port is not a number"), // the cause comes via source()
        }
    }
}
impl Error for ConfigError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self { Self::BadPort(e) => Some(e), _ => None }
    }
}
impl From<ParseIntError> for ConfigError { // what thiserror's #[from] generates
    fn from(e: ParseIntError) -> Self { Self::BadPort(e) }
}
fn port(line: &str) -> Result<u16, ConfigError> {
    Ok(line.strip_prefix("port=").ok_or(ConfigError::MissingKey("port"))?.parse()?)
}
fn main() {
    let err = port("port=http").unwrap_err();
    println!("{err}; caused by: {}", err.source().unwrap()); // port is not a number; caused by: invalid digit found in string
}

