use std::thread;

fn main() {
    // spawn: the closure must own its data ('static)
    let name = String::from("worker");
    let handle = thread::spawn(move || {
        format!("{name} computed {}", (1..=10u64).product::<u64>())
    });
    println!("{}", handle.join().unwrap()); // worker computed 3628800

    // a panic is reported through join, not propagated automatically
    let bad = thread::spawn(|| -> u32 { panic!("boom") });
    println!("thread panicked: {}", bad.join().is_err()); // true (panic message goes to stderr)

    // scoped threads may borrow locals
    let data: Vec<u64> = (1..=1_000).collect();
    let (left, right) = data.split_at(data.len() / 2);
    let (a, b) = thread::scope(|s| {
        let h1 = s.spawn(|| left.iter().sum::<u64>());
        let h2 = s.spawn(|| right.iter().sum::<u64>());
        (h1.join().unwrap(), h2.join().unwrap())
    });
    println!("{} = {}", a + b, data.iter().sum::<u64>()); // 500500 = 500500
}

use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, RwLock};
use std::thread;

fn main() {
    let totals = Arc::new(Mutex::new(Vec::new()));
    let hits = Arc::new(AtomicU64::new(0));
    let config = Arc::new(RwLock::new(String::from("v1")));

    let handles: Vec<_> = (0..4).map(|id| {
        let (totals, hits, config) = (Arc::clone(&totals), Arc::clone(&hits), Arc::clone(&config));
        thread::spawn(move || {
            let version = config.read().unwrap().clone(); // shared read lock
            hits.fetch_add(1, Ordering::Relaxed);         // lock-free counter
            let mut guard = totals.lock().unwrap();       // exclusive access
            guard.push(format!("{id}:{version}"));
        }) // guard dropped here -> unlocked
    }).collect();

    for h in handles { h.join().unwrap(); }
    *config.write().unwrap() = "v2".into();
    let mut done = totals.lock().unwrap().clone();
    done.sort();
    println!("{done:?} hits={}", hits.load(Ordering::Relaxed)); // ["0:v1", "1:v1", "2:v1", "3:v1"] hits=4
}

use std::{sync::mpsc, thread};

enum Msg { Line(String), Done(usize) }

fn main() {
    let (tx, rx) = mpsc::sync_channel::<Msg>(8); // bounded: backpressure at 8 queued
    for id in 0..3 {
        let tx = tx.clone();
        thread::spawn(move || {
            for n in 0..2 { tx.send(Msg::Line(format!("worker {id} item {n}"))).unwrap(); }
            tx.send(Msg::Done(id)).unwrap();
        }); // this clone of tx is dropped when the thread ends
    }
    drop(tx); // drop the original, or the loop below never ends

    let (mut lines, mut finished) = (Vec::new(), Vec::new());
    for msg in rx { // ends when every sender is gone
        match msg {
            Msg::Line(text) => lines.push(text),
            Msg::Done(id) => finished.push(id),
        }
    }
    finished.sort();
    println!("{} lines, done: {finished:?}", lines.len()); // 6 lines, done: [0, 1, 2]
}

use std::{future::Future, pin::pin, sync::Arc, thread::{self, Thread}};
use std::task::{Context, Poll, Wake, Waker};

struct ThreadWaker(Thread);
impl Wake for ThreadWaker {
    fn wake(self: Arc<Self>) { self.0.unpark(); } // waking = unparking the blocked thread
}
// a minimal executor: poll; if pending, park the thread until woken
fn block_on<F: Future>(fut: F) -> F::Output {
    let mut fut = pin!(fut);
    let waker = Waker::from(Arc::new(ThreadWaker(thread::current())));
    let mut cx = Context::from_waker(&waker);
    loop {
        match fut.as_mut().poll(&mut cx) {
            Poll::Ready(v) => return v,
            Poll::Pending => thread::park(),
        }
    }
}

