use std::time::Duration;
use tokio::{sync::mpsc, time::{sleep, timeout}};

async fn fetch(id: u32, ms: u64) -> String {
    sleep(Duration::from_millis(ms)).await; // yields; never use thread::sleep here
    format!("item {id}")
}
#[tokio::main]
async fn main() {
    let (a, b) = tokio::join!(fetch(1, 30), fetch(2, 10)); // concurrent, ~30 ms total
    println!("{a}, {b}");                                    // item 1, item 2
    let slow = timeout(Duration::from_millis(5), fetch(3, 50)).await;
    println!("timed out: {}", slow.is_err());                // timed out: true
    let (tx, mut rx) = mpsc::channel(16);
    for id in 0..3 {
        let tx = tx.clone();
        tokio::spawn(async move { tx.send(fetch(id, 5).await).await.unwrap() });
    }
    drop(tx);
    let mut got = Vec::new();
    while let Some(item) = rx.recv().await { got.push(item); }
    let sum = tokio::task::spawn_blocking(|| (1..=1_000_000u64).sum::<u64>()).await.unwrap();
    println!("{} items, sum = {sum}", got.len()); // 3 items, sum = 500000500000
}

