use std::slice::from_raw_parts_mut;
fn split_at_mut<T>(s: &mut [T], mid: usize) -> (&mut [T], &mut [T]) {
    let (ptr, len) = (s.as_mut_ptr(), s.len());
    assert!(mid <= len, "mid out of bounds"); // the safe API enforces the invariant
    // SAFETY: mid <= len, so [0, mid) and [mid, len) are in bounds and disjoint,
    // and both borrow from `s`, which outlives the returned slices.
    unsafe { (from_raw_parts_mut(ptr, mid), from_raw_parts_mut(ptr.add(mid), len - mid)) }
}

/// # Safety
/// `p` must be non-null, aligned and point to an initialised `u32`.
unsafe fn read_u32(p: *const u32) -> u32 {
    unsafe { *p } // 2024: an explicit unsafe block even inside an unsafe fn
}

fn main() {
    let mut data = [1, 2, 3, 4, 5];
    let (a, b) = split_at_mut(&mut data, 2);
    a[0] = 10; b[0] = 30;
    println!("{data:?}"); // [10, 2, 30, 4, 5]
    let x = 7u32;
    let p = &raw const x;                   // raw pointer without an intermediate reference
    println!("{}", unsafe { read_u32(p) }); // SAFETY: p points to a live u32 -> 7
}

