use std::{cell::Cell, marker::PhantomData, sync::{Arc, Mutex}};

fn assert_send<T: Send>() {}
fn assert_sync<T: Sync>() {}
// Owns a heap buffer through a raw pointer, so it is not Send automatically.
struct Buffer { ptr: *mut u8, len: usize }
// SAFETY: Buffer uniquely owns its allocation; nothing else aliases `ptr`.
unsafe impl Send for Buffer {}
impl Drop for Buffer {
    // SAFETY: ptr and len come from the Box<[u8]> created in main
    fn drop(&mut self) { unsafe { drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(self.ptr, self.len))) } }
}

struct SingleThreaded { _not_sync: PhantomData<Cell<()>> } // Send, but opted out of Sync

fn main() {
    assert_send::<Arc<Mutex<Vec<u8>>>>();
    assert_sync::<Mutex<Cell<u8>>>();   // Mutex makes a Send-only type Sync
    assert_send::<SingleThreaded>();
    // assert_sync::<Cell<u8>>();       // error: Cell<u8> cannot be shared between threads
    // assert_sync::<SingleThreaded>(); // error: opted out via PhantomData<Cell<()>>
    let buf = Buffer { ptr: Box::into_raw(vec![0u8; 64].into_boxed_slice()).cast(), len: 64 };
    let len = std::thread::spawn(move || { let b = buf; b.len }).join().unwrap(); // needs Buffer: Send
    println!("{len}"); // 64 (the buffer is freed on the worker thread)
}

use std::marker::PhantomData;

// Typed ID: Id<User> and Id<Order> can't be mixed; fn() -> T keeps it Send + Sync for any T.
struct Id<T> { raw: u64, _t: PhantomData<fn() -> T> }
struct User; struct Order;
fn load_user(id: Id<User>) -> u64 { id.raw }
// Raw-pointer iterator: PhantomData<&'a T> ties the items to the borrowed slice.
struct RawIter<'a, T> { ptr: *const T, end: *const T, _life: PhantomData<&'a T> }
impl<'a, T> Iterator for RawIter<'a, T> {
    type Item = &'a T;
    fn next(&mut self) -> Option<&'a T> {
        if self.ptr == self.end { return None; }
        // SAFETY: ptr is in bounds of a slice that lives for 'a
        unsafe { let item = &*self.ptr; self.ptr = self.ptr.add(1); Some(item) }
    }
}
fn raw_iter<T>(s: &[T]) -> RawIter<'_, T> {
    let r = s.as_ptr_range();
    RawIter { ptr: r.start, end: r.end, _life: PhantomData }
}
fn main() {
    let (uid, _oid) = (Id::<User> { raw: 7, _t: PhantomData }, Id::<Order> { raw: 8, _t: PhantomData });
    println!("{}", load_user(uid));                             // 7; load_user(_oid) is a type error
    println!("{:?}", raw_iter(&[1, 2, 3]).collect::<Vec<_>>()); // [1, 2, 3]
}

use std::future::{ready, Future};
use std::pin::{pin, Pin};
use std::task::{Context, Poll, Waker};

// Pin<Box<F>> is Unpin, so Counted<F> is Unpin and needs no unsafe pin projection.
struct Counted<F> { inner: Pin<Box<F>>, polls: u32 }
impl<F: Future> Future for Counted<F> {
    type Output = (F::Output, u32);
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut(); // allowed only because Self: Unpin
        this.polls += 1;
        this.inner.as_mut().poll(cx).map(|v| (v, this.polls))
    }
}

fn main() {
    // self-referential: `r` points into the future's own state across an .await
    let fut = async { let s = String::from("pinned"); let r = &s; ready(()).await; r.len() };
    // Pin::new(&mut fut) would not compile: async blocks are !Unpin
    let mut task = pin!(Counted { inner: Box::pin(fut), polls: 0 }); // pinned on the stack
    let mut cx = Context::from_waker(Waker::noop());
    if let Poll::Ready((len, polls)) = task.as_mut().poll(&mut cx) {
        println!("len {len} after {polls} poll"); // len 6 after 1 poll
    }
}

// describe-derive/Cargo.toml: [lib] proc-macro = true, dependencies syn = "2", quote = "1"
use proc_macro::TokenStream;
use quote::quote;
use syn::{parse_macro_input, Data, DeriveInput};

#[proc_macro_derive(Describe)]
pub fn derive_describe(input: TokenStream) -> TokenStream {
    let ast = parse_macro_input!(input as DeriveInput);
    let name = &ast.ident;
    let Data::Struct(data) = &ast.data else {
        return syn::Error::new_spanned(name, "Describe only supports structs")
            .to_compile_error().into();               // error points at the user's type
    };
    let fields = data.fields.iter().filter_map(|f| f.ident.as_ref()).map(|i| i.to_string());
    let (impl_g, ty_g, where_c) = ast.generics.split_for_impl();
    quote! {
        impl #impl_g #name #ty_g #where_c {
            pub fn describe() -> ::std::string::String {
                ::std::format!("{} {{ {} }}", stringify!(#name), [#(#fields),*].join(", "))
            }
        }
    }.into()
}
// user code: #[derive(Describe)] struct User { id: u32, name: String }
//            User::describe() == "User { id, name }"

use std::ffi::{c_char, c_int, c_void, CStr, CString};

unsafe extern "C" {
    safe fn abs(x: c_int) -> c_int;
    unsafe fn strlen(s: *const c_char) -> usize;
    unsafe fn qsort(base: *mut c_void, n: usize, size: usize,
                    cmp: Option<unsafe extern "C" fn(*const c_void, *const c_void) -> c_int>);
}
unsafe extern "C" fn cmp_i32(a: *const c_void, b: *const c_void) -> c_int {
    // SAFETY: qsort passes pointers to elements of our [i32] array
    unsafe { (*(a as *const i32)).cmp(&*(b as *const i32)) as c_int }
}
#[unsafe(no_mangle)]
pub extern "C" fn rust_greeting_len(name: *const c_char) -> usize {
    // SAFETY: documented contract: name is a valid, non-null, NUL-terminated string
    unsafe { CStr::from_ptr(name) }.to_bytes().len() + 7 // "Hello, " + name
}

fn main() {
    let (owned, mut nums) = (CString::new("ferris").unwrap(), [5, -2, 9, 0]); // owned outlives its pointer
    // SAFETY: valid pointer, length and element size, and a matching comparator
    unsafe { qsort(nums.as_mut_ptr().cast(), nums.len(), size_of::<i32>(), Some(cmp_i32)) };
    println!("{} {} {:?}", abs(-4), unsafe { strlen(owned.as_ptr()) }, nums); // 4 6 [-2, 0, 5, 9]
    println!("{}", rust_greeting_len(c"Rustacean".as_ptr()));                  // 16
}
